CREATE TABLE users (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL,
  display_name text NOT NULL, account_status text NOT NULL DEFAULT 'ACTIVE' CHECK (account_status IN ('ACTIVE','DISABLED')),
  platform_role text CHECK (platform_role IN ('CIVICPULSE_ADMIN','MODERATOR')), email_verified_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, user_agent text, created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_active_idx ON sessions(user_id, expires_at) WHERE revoked_at IS NULL;
CREATE TABLE verification_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, consumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE password_reset_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, consumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organizations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL CHECK (kind IN ('GOVERNMENT','NGO')), official_name text NOT NULL, display_name text, acronym text, slug text NOT NULL UNIQUE,
  logo_public_id text, description text, website text, official_email text, official_email_domains text[] NOT NULL DEFAULT '{}', phone text, address text,
  onboarding_status text NOT NULL DEFAULT 'DRAFT', verification_status text NOT NULL DEFAULT 'UNVERIFIED', active boolean NOT NULL DEFAULT true,
  submitted_at timestamptz, reviewed_at timestamptz, reviewed_by uuid REFERENCES users(id), review_notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE organization_members (organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('MEMBER','OFFICER','MANAGER','ORG_ADMIN')), membership_status text NOT NULL DEFAULT 'PENDING' CHECK (membership_status IN ('PENDING','ACTIVE','REVOKED')), invited_by uuid REFERENCES users(id), joined_at timestamptz, PRIMARY KEY (organization_id,user_id));
CREATE TABLE government_profiles (organization_id uuid PRIMARY KEY REFERENCES organizations(id) ON DELETE CASCADE, government_level text NOT NULL CHECK (government_level IN ('FEDERAL','STATE','LGA')), organization_type text NOT NULL, parent_organization_id uuid REFERENCES organizations(id), supervising_organization_id uuid REFERENCES organizations(id), mandate_text text NOT NULL, mandate_summary text, responsibilities jsonb NOT NULL DEFAULT '[]', exclusions jsonb NOT NULL DEFAULT '[]', issue_categories jsonb NOT NULL DEFAULT '[]', asset_types jsonb NOT NULL DEFAULT '[]', ownership_roles jsonb NOT NULL DEFAULT '[]', operational_contacts jsonb NOT NULL DEFAULT '{}', workflow_config jsonb NOT NULL DEFAULT '{}');
CREATE TABLE ngo_profiles (organization_id uuid PRIMARY KEY REFERENCES organizations(id) ON DELETE CASCADE, registration_authority text, registration_number text, legal_form text, registration_date date, mission text NOT NULL, focus_areas jsonb NOT NULL DEFAULT '[]', geographic_scope jsonb NOT NULL DEFAULT '[]', capabilities jsonb NOT NULL DEFAULT '[]', technical_capacity jsonb NOT NULL DEFAULT '{}', funding_profile jsonb NOT NULL DEFAULT '{}', project_history jsonb NOT NULL DEFAULT '[]');
CREATE TABLE organization_mandate_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, title text NOT NULL, source_url text, source_type text NOT NULL, issuing_authority text, effective_date date, version text, document_public_id text, notes text, verified_by uuid REFERENCES users(id), verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
